import {
  Column,
  CreateDateColumn,
  Entity,
  Index,
  OneToMany,
  PrimaryGeneratedColumn,
  UpdateDateColumn,
  Relation,
} from 'typeorm';
import { RefundEntity } from './refund.schema';
import { PaymentMethodType } from '../../../../shared-kernel/domain/value-objects/payment-method';
import { PaymentStatusType } from '../../core/domain/value-objects/payment-status';

@Entity({ name: 'payments' })
@Index('idx_payments_order_id', ['orderId'])
@Index('idx_payments_user_id', ['userId'])
@Index('idx_payments_transaction_id', ['transactionId'])
@Index('idx_payments_gateway_intent_id', ['gatewayPaymentIntentId'])
@Index('idx_payments_user_status', ['userId', 'status'])
@Index('idx_payments_status_completed_at', ['status', 'completedAt'])
export class PaymentEntity {
  @PrimaryGeneratedColumn('increment')
  id!: number;

  @Column({ name: 'order_id', type: 'int' })
  orderId!: number;

  @Column({ name: 'user_id', type: 'int', nullable: true })
  userId!: number | null;

  @Column({ type: 'decimal', precision: 10, scale: 2 })
  amount!: number;

  @Column({ type: 'varchar', length: 3 })
  currency!: string;

  @Column({ name: 'payment_method', type: 'varchar' })
  paymentMethod!: PaymentMethodType;

  @Column({ type: 'varchar' })
  status!: PaymentStatusType;

  @Column({ name: 'transaction_id', type: 'varchar', nullable: true })
  transactionId!: string | null;

  @Column({
    name: 'gateway_payment_intent_id',
    type: 'varchar',
    nullable: true,
  })
  gatewayPaymentIntentId!: string | null;

  @Column({ name: 'gateway_client_secret', type: 'varchar', nullable: true })
  gatewayClientSecret!: string | null;

  @Column({ name: 'payment_method_info', type: 'text', nullable: true })
  paymentMethodInfo!: string | null;

  @Column({
    name: 'refunded_amount',
    type: 'decimal',
    precision: 10,
    scale: 2,
    default: 0,
  })
  refundedAmount!: number;

  @Column({ name: 'failure_reason', type: 'text', nullable: true })
  failureReason!: string | null;

  @OneToMany(() => RefundEntity, (refund) => refund.payment, {
    cascade: true,
    eager: true,
  })
  refunds!: Relation<RefundEntity>[];

  @Column({ name: 'completed_at', type: 'timestamp', nullable: true })
  completedAt!: Date | null;

  @CreateDateColumn({ name: 'created_at' })
  createdAt!: Date;

  @UpdateDateColumn({ name: 'updated_at' })
  updatedAt!: Date;
}

